# extra posts for 3-a-day batch; exec'd inside make.py namespace
def rulecard(bg,sport,title,rows,foot):
    r="".join(f'<div style="background:rgba(18,51,34,.9);border-left:12px solid #C8F031;border-radius:10px;padding:30px 36px;font-family:S;font-weight:800;font-size:52px;line-height:1.2;text-align:left">{t}</div>' for t in rows)
    return f'<div class="bg">{bg}</div><div style="position:absolute;inset:0;background:rgba(7,22,14,.55)"></div>{head(sport)}<div style="position:absolute;top:170px;left:60px;right:60px"><div class="hl" style="text-align:center;font-size:70px">{title}</div><div style="display:flex;flex-direction:column;gap:24px;margin-top:50px">{r}</div><div style="font-family:S;font-weight:800;text-align:center;font-size:40px;margin-top:44px">{foot}</div></div>{icons}'
def listcard(bg,sport,title,rows,foot):
    r="".join(f'<div style="display:flex;align-items:center;gap:30px;background:rgba(7,22,14,.85);border-radius:12px;padding:22px 30px"><div style="font-family:H;font-size:80px;color:#C8F031;width:90px;text-align:center;line-height:1">{n}</div><div style="text-align:left"><div style="font-family:H;font-size:44px;line-height:1.1">{p}</div><div style="font-family:S;font-weight:700;font-size:26px;margin-top:6px">{y}</div></div></div>' for n,p,y in rows)
    return f'<div class="bg">{bg}</div><div style="position:absolute;inset:0;background:rgba(7,22,14,.5)"></div>{head(sport)}<div style="position:absolute;top:160px;left:60px;right:60px;text-align:center"><div class="hl" style="font-size:70px">{title}</div><div style="display:flex;flex-direction:column;gap:16px;margin-top:44px">{r}</div><div style="font-family:S;font-weight:800;font-size:42px;margin-top:40px">{foot}</div></div>{icons}'
